// findIPowerSuffix is used in ParseResourceLimits to parse memory units.
func findIPowerSuffix(raw string, suffi []string, base int64) (suffix string, m int64) {
	m = 1
	for _, s := range suffi {
		m *= base
		if strings.HasSuffix(raw, s) {
			return s, m
		}
	}
	return "", 0
}

